import React, { useState } from 'react';

const Carousel3D = ({ movies = [] }) => {
  const [currentIndex, setCurrentIndex] = useState(2);

  // 데이터가 없을 경우 대체할 기본 더미 데이터
  const displayMovies = movies.length > 0 ? movies : [
    { id: 0, title: "Dune 2", poster_path: "/placeholder1.jpg" },
    { id: 1, title: "Wicked", poster_path: "/placeholder2.jpg" },
    { id: 2, title: "Interstellar", poster_path: "/placeholder3.jpg" },
    { id: 3, title: "Avatar", poster_path: "/placeholder4.jpg" },
    { id: 4, title: "Joker", poster_path: "/placeholder5.jpg" },
  ];

  const total = displayMovies.length;

  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);

  return (
    <div className="w-full py-10 flex flex-col items-center justify-center bg-[#0b090e] overflow-hidden">
      
      {/* 3D 스테이지 영역 (Flexbox로 완벽한 중앙 정렬) */}
      <div 
        className="relative w-full max-w-5xl h-[380px] flex items-center justify-center"
        style={{ perspective: '1200px' }}
      >
        {displayMovies.map((movie, index) => {
          let offset = (index - currentIndex + total) % total;
          if (offset > total / 2) offset -= total;

          // 각 카드의 위치 및 3D 회전값 계산
          const translateX = offset * 190;
          const translateZ = -Math.abs(offset) * 70;
          const rotateY = offset * -18;
          const scale = Math.max(1 - Math.abs(offset) * 0.1, 0.75);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: total - Math.abs(offset),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.5s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              className={`absolute w-48 h-72 rounded-xl overflow-hidden cursor-pointer shadow-2xl border bg-zinc-900 ${
                offset === 0 
                  ? 'border-purple-500 shadow-[0_0_25px_rgba(168,85,247,0.4)]' 
                  : 'border-white/10 brightness-75'
              }`}
            >
              {movie.poster_path && movie.poster_path.startsWith('/') ? (
                <img 
                  src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} 
                  alt={movie.title || 'Movie Poster'} 
                  className="w-full h-full object-cover pointer-events-none" 
                />
              ) : (
                <div className="w-full h-full bg-zinc-800 flex items-center justify-center text-xs text-zinc-400 p-2 text-center">
                  {movie.title || 'Movie Poster'}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 좌우 네비게이션 버튼 */}
      <div className="flex items-center gap-6 mt-6 z-20">
        <button 
          onClick={handlePrev} 
          className="w-10 h-10 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer font-bold"
        >
          &larr;
        </button>
        <div className="flex gap-2">
          {displayMovies.map((_, idx) => (
            <span 
              key={idx}
              onClick={() => setCurrentIndex(idx)}
              className={`h-2 rounded-full cursor-pointer transition-all ${
                idx === currentIndex ? 'bg-purple-500 w-6' : 'bg-white/20 w-2'
              }`}
            />
          ))}
        </div>
        <button 
          onClick={handleNext} 
          className="w-10 h-10 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer font-bold"
        >
          &rarr;
        </button>
      </div>

    </div>
  );
};

export default Carousel3D;
